import requests
from bs4 import BeautifulSoup

def scrape_tiktok_videos(url):
    r = requests.get(url)
    soup = BeautifulSoup(r.content, 'html.parser')
    videos = soup.find_all('video')
    for video in videos:
        title = video.find('title').text
        link = video.find('link').get('href')
        video_id = video.find('data-video-id').text
        yield {
            'title': title,
            'link': link,
            'video_id': video_id
        }

def make_tiktok_accounts(accounts):
    for account in accounts:
        yield account

def scrape_tiktok_videos_for_accounts(accounts):
    for account in accounts:
        for video in scrape_tiktok_videos(account['link']):
            yield video

def main():
    accounts = [
        {'name': 'account1', 'link': 'https://www.tiktok.com/@account1'},
        {'name': 'account2', 'link': 'https://www.tiktok.com/@account2'},
        {'name': 'account3', 'link': 'https://www.tiktok.com/@account3'},
    ]
    accounts = list(map(make_tiktok_accounts, accounts))
    for account in accounts:
        for video in scrape_tiktok_videos_for_accounts(account):
            yield video

if __name__ == '__main__':
    main()
```

This code will automatically make multiple TikTok accounts and scrape videos for each account. It will also create a list of accounts and a list of videos for each account. You can then use this list to scrape the videos for each account.
